sys_security_acl.script:
// Get the attempt to check ownership
var attemptGR = new GlideRecord('x_1879300_learning_assessment_attempts');
if (attemptGR.get(current.attempt)) {
    // Students can only see their own responses
    if (gs.hasRole('x_1879300_learning.student') && !gs.hasRole('x_1879300_learning.teaching_assistant')) {
        return attemptGR.getValue('user') == gs.getUserID();
    }

    // TAs and Instructors can see responses for their courses
    if (gs.hasRole('x_1879300_learning.teaching_assistant')) {
        var assessmentGR = new GlideRecord('x_1879300_learning_assessments');
        if (assessmentGR.get(attemptGR.assessment)) {
            if (assessmentGR.lesson) {
                var lessonGR = new GlideRecord('x_1879300_learning_lessons');
                if (lessonGR.get(assessmentGR.lesson)) {
                    var courseGR = new GlideRecord('x_1879300_learning_courses');
                    if (courseGR.get(lessonGR.course)) {
                        return gs.hasRole('x_1879300_learning.admin') || 
                               courseGR.getValue('created_by') == gs.getUserID();
                    }
                }
            }
            if (assessmentGR.course) {
                var courseGR = new GlideRecord('x_1879300_learning_courses');
                if (courseGR.get(assessmentGR.course)) {
                    return gs.hasRole('x_1879300_learning.admin') || 
                           courseGR.getValue('created_by') == gs.getUserID();
                }
            }
        }
    }
}

return gs.hasRole('x_1879300_learning.admin');
